func (q *Queries) SpendTotals(ctx context.Context, arg SpendTotalsParams) (SpendTotalsRow, error) {
	row := q.db.QueryRow(ctx, spendTotals,
		arg.FromDay,
		arg.ToDay,
		arg.Route,
		arg.Model,
	)
	var i SpendTotalsRow
	err := row.Scan(&i.CostMicros, &i.InputTokens, &i.OutputTokens)
	return i, err
}

const statsFilterModels = `-- name: StatsFilterModels :many
SELECT DISTINCT model FROM stats_hourly WHERE hour >= $1 AND model <> '' ORDER BY model
`

// StatsFilterModels lists the models of the hours from since on, without
// the empty one of investigations that have none.
func (q *Queries) StatsFilterModels(ctx context.Context, since time.Time) ([]string, error) {
	rows, err := q.db.Query(ctx, statsFilterModels, since)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var model string
		if err := rows.Scan(&model); err != nil {
			return nil, err
		}
		items = append(items, model)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

